presets.customCss:
/* 长夜＆机械之心➠线上心声美化，建议修改key 给版式取值＜40 使用更佳*/
.xs-voice-wrap-night {
  background: #000000 !important;
  backdrop-filter: blur(28px);
  -webkit-backdrop-filter: blur(28px);
  border-radius: 0px !important;
  padding: 24px 16px 32px;
  position: relative;
  overflow: hidden;
  font-family: system-ui, sans-serif;
  border:1px solid #333;
}
.xs-title-night {
  font-family:"Cinzel",serif;
  font-style:italic;
  font-size:22px;
  color:#ffffff;
  margin:0 0 8px;
  position:relative; z-index:2;
}
.xs-ecg-top-night, .xs-ecg-bottom-night {
  position:absolute; left:0; right:0; height:18px; opacity:.7; pointer-events:none;
}
.xs-ecg-top-night { top:60px; }
.xs-ecg-bottom-night { bottom:0; }
.xs-ecg-top-night svg, .xs-ecg-bottom-night svg { width:100%; height:100%; }
.xs-center-line-night {
  position:absolute; left:50%; top:88px; bottom:36px;
  width:2px; transform:translateX(-50%);
  background:#444444; z-index:1;
}
.xs-list-night {
  position:relative; z-index:2;
  display:flex; flex-direction:column; gap:4px;
  margin-top:24px;
}
.xs-row-night {
  display:flex; align-items:center; position:relative;
}
.xs-bubble-night {
  width:46%; padding:9px 14px;
  background: #111111;
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-radius: 0px !important;
  border:1px solid #333;
  box-shadow: 0 2px 12px rgba(0,0,0,.4);
  font-size:11.5px; line-height:1.6; color:#ffffff;
  position:relative;
  white-space:normal; word-break:break-word;
}
.xs-bubble-night .content-night:empty::after {
  content:"机械之心";
  font-style:italic;
  color:#777777;
  opacity:.6;
}
.left-night { margin-right:auto; }
.right-night { margin-left:auto; }
.tag-night {
  display:block; font-size:10px; letter-spacing:1px;
  color:#bbbbbb; opacity:.9; margin-bottom:2px;
}
.xs-favor-ecg-night {
  display:flex; align-items:center; gap:6px; margin-top:6px;
}
.xs-favor-ecg-night .line-night { flex:1; height:14px; }
.xs-favor-ecg-night .heart-night { width:12px; height:12px; flex-shrink:0; }
.xs-bubble-night [class*="bar"] { display:none !important; }
.xs-node-night {
  position:absolute; left:50%; top:50%;
  transform:translate(-50%,-50%) rotate(45deg);
  width:12px; height:12px;
  border-radius:0px !important;
  background:transparent !important;
  border:2px solid #eee;
  box-shadow:0 0 0 4px rgba(255,255,255,.08);
  z-index:3;
}
